// lab/source/tables.mjs: writes packages/engine/src/source/tables.ts, the source reader's generated tables, from the
// engine's own (src/pdf-reader/engine/rules): LaTeXML's argument prototypes (latexml-args.mjs, itself generated by
// scripts/latexml-args.mjs from LaTeXML), the role table's hand forms of arg-roles.mjs (CURATED, CURATED_ENVS, DELIMITED,
// NOT_FRONT_TEXT, MORE_FRONT, VALUES: read from its text, since it does not export them), the kernel's text symbols
// (text-symbols.mjs), a display's opening (translate/mt.mjs DISPLAY) and TeX's spaces in math (tex-kernel.mjs spaceSource). One source of each until the switch, when the package's copy becomes the only one and the
// generators write it directly.
//   node lab/source/tables.mjs [--check]
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'

const RULES = new URL('../../src/pdf-reader/engine/rules/', import.meta.url)
const OUT = new URL('../../packages/engine/src/source/tables.ts', import.meta.url)
const L = await import(new URL('latexml-args.mjs', RULES).href)
const { TEXT_SYMBOLS } = await import(new URL('text-symbols.mjs', RULES).href)
const roles = readFileSync(new URL('arg-roles.mjs', RULES), 'utf8')
const { spaceSource } = await import(new URL('tex-kernel.mjs', RULES).href)
// (a display's opening, the wire's: translate/mt.mjs DISPLAY, read from its text, since importing mt.mjs reads the core's TS)
const mt = readFileSync(new URL('../translate/mt.mjs', RULES), 'utf8')
const DISPLAY = /^export const DISPLAY = \/(.+)\/\n/m.exec(mt)?.[1]
if (!DISPLAY) throw new Error('no DISPLAY in translate/mt.mjs')

/** the value of `const NAME = <literal>` in a module's text: an object or array literal (or `new Set([...])`, or
 *  `Object.freeze(...)`), braces counted outside strings and comments */
function literal(text, name, scope = {}) {
  const at = text.indexOf(`const ${name} = `)
  if (at < 0) throw new Error(`no ${name}`)
  let i = at + `const ${name} = `.length
  const start = i
  let depth = 0
  for (; i < text.length; i++) {
    const c = text[i]
    if (c === "'" || c === '"' || c === '`') {
      for (i++; text[i] !== c; i++) if (text[i] === '\\') i++
      continue
    }
    if (c === '/' && text[i + 1] === '/') {
      i = text.indexOf('\n', i)
      continue
    }
    if (c === '/' && text[i + 1] === '*') {
      i = text.indexOf('*/', i) + 1
      continue
    }
    if ('{[('.includes(c)) depth++
    else if ('}])'.includes(c) && --depth === 0) break
  }
  const src = text.slice(start, i + 1)
  const value = new Function(...Object.keys(scope), `return ${src}`)(...Object.values(scope))
  return value instanceof Set ? [...value] : value
}

// (in the order they name each other: CURATED spreads DELIMITED)
const hand = {}
for (const n of ['DELIMITED', 'CURATED', 'CURATED_ENVS', 'NOT_FRONT_TEXT', 'MORE_FRONT', 'VALUES']) hand[n] = literal(roles, n, hand)
const j = v => JSON.stringify(v)
const out = `// Generated by lab/source/tables.mjs from src/pdf-reader/engine/rules (latexml-args.mjs: LaTeXML at ${L.LATEXML_COMMIT},
// public domain, docs/THIRD_PARTY.md; arg-roles.mjs' hand forms; text-symbols.mjs). Do not edit: run the script again.
// The role table's forms, a pair of characters each (shape, role: arg-roles.mjs' header): LaTeXML's for every LaTeX document
// (COMMANDS, ENVIRONMENTS; '?' where LaTeXML reads them in code) and by package or class (PACKAGE_*: [form, binding…], a
// binding by BINDINGS' index, loading those REQUIRES names), the front matter's hooks (FRONT), and the forms written out by
// hand where LaTeXML's say less than the command takes (CURATED, CURATED_ENVS, DELIMITED).
export const LATEXML_COMMIT = ${j(L.LATEXML_COMMIT)}
export const BINDINGS: readonly string[] = ${j(L.BINDINGS)}
export const REQUIRES: readonly (readonly number[])[] = ${j(L.REQUIRES)}
export const COMMANDS: Readonly<Record<string, string>> = ${j(L.COMMANDS)}
export const PACKAGE_COMMANDS: Readonly<Record<string, readonly (readonly (string | number)[])[]>> = ${j(L.PACKAGE_COMMANDS)}
export const ENVIRONMENTS: Readonly<Record<string, string>> = ${j(L.ENVIRONMENTS)}
export const PACKAGE_ENVIRONMENTS: Readonly<Record<string, readonly (readonly (string | number)[])[]>> = ${j(L.PACKAGE_ENVIRONMENTS)}
export const FRONT: Readonly<Record<string, readonly [string, number]>> = ${j(L.FRONT)}
export const CURATED: Readonly<Record<string, string>> = ${j(hand.CURATED)}
export const CURATED_ENVS: Readonly<Record<string, string>> = ${j(hand.CURATED_ENVS)}
export const DELIMITED: Readonly<Record<string, string>> = ${j(hand.DELIMITED)}
export const NOT_FRONT_TEXT: readonly string[] = ${j(hand.NOT_FRONT_TEXT)}
export const MORE_FRONT: Readonly<Record<string, readonly [string, number]>> = ${j(hand.MORE_FRONT)}
export const VALUES: readonly string[] = ${j(hand.VALUES)}
export const TEXT_SYMBOLS: Readonly<Record<string, string>> = ${j(TEXT_SYMBOLS)}
/** a display's opening (translate/mt.mjs DISPLAY), and the spaces TeX sets in math (rules/tex-kernel.mjs spaceSource) */
export const DISPLAY_SOURCE = ${j(DISPLAY)}
export const MATH_SPACE_SOURCE = ${j(spaceSource({ math: true }))}
`
// (as the package's formatter writes it: Biome formats packages/**)
const formatted = execFileSync('pnpm', ['exec', 'biome', 'format', '--stdin-file-path=packages/engine/src/source/tables.ts'], {
  input: out,
  cwd: new URL('../..', import.meta.url).pathname,
  maxBuffer: 1 << 26,
}).toString()
if (process.argv.includes('--check')) {
  if (readFileSync(OUT, 'utf8') !== formatted) {
    console.error('tables.ts differs from its sources: run node lab/source/tables.mjs')
    process.exit(1)
  }
} else writeFileSync(OUT, formatted)
console.log(`tables.ts: ${formatted.length} characters`)
